package com.aistock.prediction.comparison;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;import java.time.*;import java.util.*;import java.security.*;
public final class ComparisonTestEvidence {
 public static final ObjectMapper M=new ObjectMapper().findAndRegisterModules();
 public static ObjectNode sample(String stock,String[] prices,String[] volumes){var n=M.createObjectNode();n.put("evidenceId",UUID.randomUUID().toString()).put("instrumentId",stock).put("rawVersionId",UUID.randomUUID().toString()).put("rawContentHash","a".repeat(64)).put("provider","baostock").put("basis","BACKWARD").put("from","2026-07-09").put("to","2026-10-09").put("capturedAt","2026-10-12T00:00:00Z").put("sourcePayloadHash","b".repeat(64));var cal=n.putArray("calendar");LocalDate.parse("2026-07-09").datesUntil(LocalDate.parse("2026-10-10")).forEach(d->cal.addObject().put("date",d.toString()).put("open",!d.isBefore(LocalDate.parse("2026-10-07")))) ;var days=n.putArray("days");for(int i=0;i<3;i++){var d=days.addObject().put("date",LocalDate.parse("2026-10-07").plusDays(i).toString()).put("priceState",prices[i]==null?"MISSING":"VERIFIED").put("volumeState",volumes[i]==null?"MISSING":"VERIFIED");if(prices[i]==null)d.putNull("backwardClose");else d.put("backwardClose",prices[i]);if(volumes[i]==null)d.putNull("volumeShares");else d.put("volumeShares",volumes[i]);}rehash(n);return n;}
 public static void rehash(ObjectNode n){var cal=new ArrayList<Object>();n.path("calendar").forEach(d->cal.add(List.of(d.path("date").asText(),d.path("open").asBoolean())));n.put("calendarHash",hash(cal));var days=new ArrayList<Object>();n.path("days").forEach(d->days.add(Arrays.asList(d.path("date").asText(),d.path("priceState").asText(),d.path("backwardClose").isNull()?null:d.path("backwardClose").asText(),d.path("volumeState").asText(),d.path("volumeShares").isNull()?null:d.path("volumeShares").asText())));n.put("contentHash",hash(List.of(n.path("instrumentId").asText(),n.path("rawVersionId").asText(),n.path("from").asText(),n.path("to").asText(),"baostock","baostock-comparison-backward-close-v1",n.path("calendarHash").asText(),days)));}
 public static String hash(Object v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(M.writeValueAsBytes(v)));}catch(Exception e){throw new IllegalStateException(e);}}
}
